const crypto = require('crypto');
const { promisify } = require('util');
const express = require('express');
const session = require('express-session');

const scrypt = promisify(crypto.scrypt);
const isProd = process.env.NODE_ENV === 'production';

// ---------- Password hashing (scrypt, built into Node) ----------

// OWASP-recommended scrypt parameters (~32 MB per hash).
const SCRYPT_PARAMS = { N: 2 ** 15, r: 8, p: 3 };
const SCRYPT_MAXMEM = 64 * 1024 * 1024;
const KEY_LEN = 32;
const MAX_PASSWORD_LEN = 1024; // stop huge inputs from burning CPU

// Stored as scrypt$N$r$p$salt$hash so parameters can be raised later
// without breaking existing hashes.
async function hashPassword(password) {
  const { N, r, p } = SCRYPT_PARAMS;
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, KEY_LEN, { N, r, p, maxmem: SCRYPT_MAXMEM });
  return ['scrypt', N, r, p, salt.toString('base64'), key.toString('base64')].join('$');
}

async function verifyPassword(password, stored) {
  const [scheme, N, r, p, salt, hash] = stored.split('$');
  if (scheme !== 'scrypt') return false;
  const expected = Buffer.from(hash, 'base64');
  const actual = await scrypt(password, Buffer.from(salt, 'base64'), expected.length, {
    N: Number(N),
    r: Number(r),
    p: Number(p),
    maxmem: SCRYPT_MAXMEM,
  });
  return crypto.timingSafeEqual(actual, expected);
}

// Verified against when the username doesn't exist, so unknown users take as
// long as known ones and can't be enumerated by response time.
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// ---------- Rate limiting of login attempts ----------

function createLimiter({ max, windowMs }) {
  const hits = new Map(); // key -> { count, resetAt }

  setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of hits) if (entry.resetAt <= now) hits.delete(key);
  }, windowMs).unref();

  return {
    // Counts the attempt up front, before the password is checked, so a burst
    // of parallel requests can't all slip past the limit.
    consume(key) {
      const now = Date.now();
      let entry = hits.get(key);
      if (!entry || entry.resetAt <= now) {
        entry = { count: 0, resetAt: now + windowMs };
        hits.set(key, entry);
      }
      entry.count++;
      return {
        allowed: entry.count <= max,
        retryAfter: Math.ceil((entry.resetAt - now) / 1000),
      };
    },
    refund(key) {
      const entry = hits.get(key);
      if (entry && entry.count > 0) entry.count--;
    },
    reset(key) {
      hits.delete(key);
    },
  };
}

const WINDOW_MS = 15 * 60 * 1000;
// Per account: stops guessing one user's password, even from many IPs.
const accountLimiter = createLimiter({ max: 5, windowMs: WINDOW_MS });
// Per IP: stops one client spraying passwords across many accounts.
const ipLimiter = createLimiter({ max: 20, windowMs: WINDOW_MS });

// ---------- User store (in-memory; replace with your database) ----------

const users = new Map(); // normalized username -> { id, username, passwordHash }

const normalizeUsername = (username) => username.trim().toLowerCase();

// ---------- App ----------

const app = express();

// Needed behind a reverse proxy so req.ip is the client's address and secure
// cookies work. Set to the number of proxy hops, e.g. TRUST_PROXY=1.
if (process.env.TRUST_PROXY) app.set('trust proxy', Number(process.env.TRUST_PROXY));

if (isProd && !process.env.SESSION_SECRET) {
  throw new Error('SESSION_SECRET must be set in production');
}

app.use(express.json({ limit: '10kb' }));
app.use(
  session({
    name: 'sid',
    secret: process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: isProd,
      maxAge: 8 * 60 * 60 * 1000,
    },
    // Default MemoryStore is for development only: use connect-redis,
    // connect-pg-simple, etc. in production.
  })
);

function parseCredentials(body) {
  const { username, password } = body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  const name = normalizeUsername(username);
  if (!name || name.length > 64 || !password || password.length > MAX_PASSWORD_LEN) return null;
  return { name, password };
}

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

function tooManyAttempts(res, retryAfter) {
  res.set('Retry-After', String(retryAfter));
  return res.status(429).json({ error: 'Too many login attempts. Try again later.' });
}

app.post('/register', async (req, res, next) => {
  try {
    const creds = parseCredentials(req.body);
    if (!creds || creds.password.length < 8) {
      return res.status(400).json({ error: 'Username and a password of at least 8 characters are required' });
    }
    if (users.has(creds.name)) return res.status(409).json({ error: 'Username already taken' });

    const passwordHash = await hashPassword(creds.password);
    if (users.has(creds.name)) return res.status(409).json({ error: 'Username already taken' });
    users.set(creds.name, { id: crypto.randomUUID(), username: creds.name, passwordHash });
    res.status(201).json({ username: creds.name });
  } catch (err) {
    next(err);
  }
});

app.post('/login', async (req, res, next) => {
  try {
    const creds = parseCredentials(req.body);
    if (!creds) return res.status(400).json({ error: 'Username and password are required' });

    const ipHit = ipLimiter.consume(req.ip);
    if (!ipHit.allowed) return tooManyAttempts(res, ipHit.retryAfter);
    const accountHit = accountLimiter.consume(creds.name);
    if (!accountHit.allowed) return tooManyAttempts(res, accountHit.retryAfter);

    const user = users.get(creds.name);
    const passwordOk = await verifyPassword(creds.password, user ? user.passwordHash : await dummyHash);
    if (!user || !passwordOk) {
      // Same response for unknown user and wrong password.
      return res.status(401).json({ error: 'Invalid username or password' });
    }

    // Only failures should count against the limits.
    accountLimiter.reset(creds.name);
    ipLimiter.refund(req.ip);

    // New session ID on login prevents session fixation.
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.username = user.username;
      req.session.save((err) => {
        if (err) return next(err);
        res.json({ username: user.username });
      });
    });
  } catch (err) {
    next(err);
  }
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ username: req.session.username });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`Listening on http://localhost:${port}`));
}

module.exports = app;

const test = require('node:test');
const assert = require('node:assert');
const app = require('./app');

let server;
let base;

test.before(async () => {
  server = app.listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  base = `http://localhost:${server.address().port}`;
});

test.after(() => server.close());

function post(path, body, cookie) {
  return fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(cookie && { Cookie: cookie }) },
    body: JSON.stringify(body),
  });
}

const sessionCookie = (res) => res.headers.get('set-cookie')?.split(';')[0];

test('login, session, logout', async () => {
  const creds = { username: 'Alice', password: 'correct horse battery' };
  assert.strictEqual((await post('/register', creds)).status, 201);

  assert.strictEqual((await fetch(base + '/me')).status, 401);

  const bad = await post('/login', { ...creds, password: 'wrong password' });
  assert.strictEqual(bad.status, 401);
  assert.strictEqual(sessionCookie(bad), undefined);

  const unknown = await post('/login', { username: 'nobody', password: 'whatever123' });
  assert.strictEqual(unknown.status, 401);
  assert.deepStrictEqual(await unknown.json(), await bad.json());

  const good = await post('/login', creds);
  assert.strictEqual(good.status, 200);
  const cookie = sessionCookie(good);
  assert.match(cookie, /^sid=/);
  assert.match(good.headers.get('set-cookie'), /HttpOnly/);

  const me = await fetch(base + '/me', { headers: { Cookie: cookie } });
  assert.deepStrictEqual(await me.json(), { username: 'alice' });

  assert.strictEqual((await post('/logout', {}, cookie)).status, 204);
  assert.strictEqual((await fetch(base + '/me', { headers: { Cookie: cookie } })).status, 401);
});

test('locks the account after 5 failed attempts', async () => {
  const creds = { username: 'bob', password: 'another good password' };
  await post('/register', creds);

  // Sent in parallel to check the limit can't be raced.
  const attempts = await Promise.all(
    Array.from({ length: 8 }, () => post('/login', { ...creds, password: 'guess' }))
  );
  const statuses = attempts.map((res) => res.status).sort();
  assert.deepStrictEqual(statuses, [401, 401, 401, 401, 401, 429, 429, 429]);

  // Even the correct password is refused while locked.
  const locked = await post('/login', creds);
  assert.strictEqual(locked.status, 429);
  assert.ok(Number(locked.headers.get('retry-after')) > 0);
});

test('successful logins do not use up the limit', async () => {
  const creds = { username: 'carol', password: 'yet another password' };
  await post('/register', creds);
  for (let i = 0; i < 7; i++) {
    assert.strictEqual((await post('/login', creds)).status, 200);
  }
});

